@layer cascivo.component {
  /*
   * Children are wrapped in a single element so the loading Spinner can be a sibling. That
   * wrapper has to be a flex row itself: with a plain <span>, the button's own `gap` applies
   * between the spinner and the wrapper, and an icon composed next to a label INSIDE it gets
   * no spacing at all — `<Button><ExternalLink />Visit</Button>` rendered touching
   * (2026-08-08 report A). The wrapper's DOM shape is documented on ButtonProps, because
   * layout CSS written against `.button > span` targets this element and not the label.
   */
  .label {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }

  .button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-weight: var(--cascivo-font-medium);
    line-height: var(--cascivo-leading-none);
    white-space: nowrap;
    cursor: pointer;
    /* `asChild` renders this styling onto a real <a>, where the UA's `a[href]`
       underline would otherwise survive and make the button label underlined. */
    text-decoration: none;
    border: 1px solid transparent;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out),
      scale var(--cascivo-duration-75) var(--cascivo-ease-out);
    border-radius: var(--cascivo-button-radius, var(--cascivo-radius-control));

    /* Tactile press. `scale` is composited, so this costs nothing, and it reads as physical
       depression rather than as a colour change alone. Excluded on a disabled control,
       which must not appear to respond. Collapses with the duration token under
       prefers-reduced-motion. */
    &:active:not(:disabled):not([aria-disabled='true']) {
      scale: 0.97;
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    /* An <a> can't be :disabled — under `asChild` the disabled state arrives as
       aria-disabled, so both selectors must carry the same visuals. */
    &:disabled,
    &[aria-disabled='true'] {
      opacity: 0.5; /* static fallback */
      opacity: var(--cascivo-disabled-opacity, 0.5);
      cursor: not-allowed;
      pointer-events: none;
    }

    /* Sizes */
    &[data-size='sm'] {
      height: var(--cascivo-control-height-sm);
      padding-inline: var(--cascivo-space-3);
      font-size: var(--cascivo-text-ui); /* canonical control-label role (= text-sm) */
    }

    &[data-size='md'] {
      height: var(--cascivo-control-height-md);
      padding-inline: var(--cascivo-space-4);
      padding-block: 0.5rem; /* static fallback — non-supporting browsers */
      padding-block: --cascivo-step(2); /* progressive enhancement — Chrome 133+ */
      font-size: var(--cascivo-text-ui); /* canonical control-label role (= text-sm) */
    }

    &[data-size='lg'] {
      height: var(--cascivo-control-height-lg);
      padding-inline: var(--cascivo-space-6);
      font-size: var(--cascivo-text-body); /* larger control label (= text-base) */
    }

    /* Coarse-pointer touch targets — raise minimum to 44px, desktop density unchanged */
    @media (pointer: coarse) {
      &[data-size='sm'] {
        min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
      }
      &[data-size='md'] {
        min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
      }
    }

    /*
     * Variants.
     *
     * Each background is a per-variant component token over its semantic default, so one
     * button family can be re-pointed without moving the semantic tier underneath every
     * other component that reads it. Setting `--cascivo-color-primary` recolours primary
     * buttons AND every other primary surface in the subtree; that is the right lever for a
     * brand and the wrong one for "this dialog's confirm button is green".
     *
     * `docs/STYLING-INTERNALS.md` used to name a `--cascivo-button-bg` for exactly this job.
     * It never existed — the ladder's first rung pointed at a token that silently did
     * nothing on the component people restyle most. These are that rung, made real.
     *
     * **The foreground does not follow.** `color` stays on the semantic token, so a
     * background light enough to need dark text will fail contrast until you set the paired
     * `--cascivo-color-*-fg` too. Deliberate: a per-variant foreground knob is a separate
     * decision, and inventing one here would be guessing at an API nobody asked for. The
     * manifest and the docs both say so.
     */
    &[data-variant='primary'] {
      background-color: var(--cascivo-button-primary-bg, var(--cascivo-color-primary));
      color: var(--cascivo-color-primary-fg);

      &:hover:not(:disabled) {
        background-color: var(
          --cascivo-button-primary-bg-hover,
          var(--cascivo-color-primary-hover)
        );
      }

      &:active:not(:disabled) {
        background-color: var(
          --cascivo-button-primary-bg-active,
          var(--cascivo-color-primary-active)
        );
      }
    }

    &[data-variant='secondary'] {
      background-color: var(--cascivo-button-secondary-bg, var(--cascivo-color-secondary));
      color: var(--cascivo-color-secondary-content);

      &:hover:not(:disabled) {
        background-color: var(
          --cascivo-button-secondary-bg-hover,
          var(--cascivo-color-secondary-hover)
        );
      }
    }

    /* Ghost's default is `transparent`, not a token — the knob is for tinting it. */
    &[data-variant='ghost'] {
      background-color: var(--cascivo-button-ghost-bg, transparent);
      color: var(--cascivo-color-text);

      &:hover:not(:disabled) {
        background-color: var(--cascivo-button-ghost-bg-hover, var(--cascivo-color-bg-subtle));
      }
    }

    &[data-variant='destructive'] {
      background-color: var(--cascivo-button-destructive-bg, var(--cascivo-color-destructive));
      color: var(--cascivo-color-text-on-destructive);

      &:hover:not(:disabled) {
        background-color: var(
          --cascivo-button-destructive-bg-hover,
          var(--cascivo-color-destructive-hover)
        );
      }
    }
  }
}

@media (forced-colors: active) {
  .button {
    border: 1px solid ButtonText;
  }

  .button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .button:disabled {
    border-color: GrayText;
    color: GrayText;
  }
}
